            Tabbit::CheckColumn(Reader, Column, TEXT("Loot.Weight"), Tabbit::KindArray, false, Tabbit::ElementMask(Tabbit::ElementI32) | Tabbit::ElementMask(Tabbit::ElementVarint));
            Cursor.Open(Reader, Column, Header.RowCount, TEXT("Loot.Weight"));

