        case 2:
            Tabbit::CheckColumn(Reader, Column, TEXT("Drop.Grades"), Tabbit::KindArray, false, Tabbit::ElementMask(Tabbit::ElementVarint));
            Cursor.Open(Reader, Column, Header.RowCount, TEXT("Drop.Grades"));

